package com.chesspulseai.service; import org.junit.jupiter.api.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; class ChessPositionServiceTest {private final ChessPositionService chess=new ChessPositionService();@Test void createsFenAndSanForLegalMove(){var result=chess.apply(List.of(),"e2e4");assertEquals("e4",result.san());assertTrue(result.fen().startsWith("rnbqkbnr/pppppppp/8/8/4P3"));}@Test void rejectsIllegalMove(){assertThrows(RuntimeException.class,()->chess.apply(List.of(),"e2e5"));}}
